    charge_no_card: "\u26A0\uFE0F \u0634\u0645\u0627\u0631\u0647 \u06A9\u0627\u0631\u062A \u0647\u0646\u0648\u0632 \u062F\u0631 \u067E\u0646\u0644 \u062A\u0646\u0638\u06CC\u0645 \u0646\u0634\u062F\u0647.\n\u0645\u0628\u0644\u063A \u0627\u0646\u062A\u062E\u0627\u0628\u06CC: *{amount:,} \u062A\u0648\u0645\u0627\u0646*\n\n\u0628\u0647 \u067E\u0634\u062A\u06CC\u0628\u0627\u0646\u06CC \u067E\u06CC\u0627\u0645 \u0628\u062F\u0647 \u062A\u0627 \u0634\u0645\u0627\u0631\u0647 \u06A9\u0627\u0631\u062A \u0631\u0627 \u0628\u06AF\u06CC\u0631\u06CC.",
    btn_copy_card: " \u06A9\u067E\u06CC \u0634\u0645\u0627\u0631\u0647 \u06A9\u0627\u0631\u062A",
    btn_change_amount: "\u270F\uFE0F \u062A\u063A\u06CC\u06CC\u0631 \u0645\u0628\u0644\u063A",
    card_copied: "\u0634\u0645\u0627\u0631\u0647 \u06A9\u0627\u0631\u062A \u0631\u0627 \u0644\u0645\u0633 \u06A9\u0646 \u0648 \u06A9\u067E\u06CC \u06A9\u0646.",
    card_missing: "\u0634\u0645\u0627\u0631\u0647 \u06A9\u0627\u0631\u062A \u062A\u0646\u0638\u06CC\u0645 \u0646\u0634\u062F\u0647.",
    receipt_need_content: "\u0639\u06A9\u0633 \u0631\u0633\u06CC\u062F\u060C \u0641\u0627\u06CC\u0644\u060C \u06CC\u0627 \u0634\u0645\u0627\u0631\u0647 \u067E\u06CC\u06AF\u06CC\u0631\u06CC \u0644\u0627\u0632\u0645 \u0627\u0633\u062A.\n\u06CC\u06A9\u06CC \u0631\u0627 \u0647\u0645\u06CC\u0646\u200C\u062C\u0627 \u0628\u0641\u0631\u0633\u062A.",
    receipt_submitted: "\u2705 *\u0645\u0645\u0646\u0648\u0646 \u0627\u0632 \u067E\u0631\u062F\u0627\u062E\u062A \u0648 \u0627\u0639\u062A\u0645\u0627\u062F\u062A* \u2764\uFE0F\n\n\u{1F4CB} *\u062E\u0644\u0627\u0635\u0647 \u067E\u0631\u062F\u0627\u062E\u062A:*\n\u{1F516} \u0634\u0646\u0627\u0633\u0647 \u0631\u0633\u06CC\u062F: `{rid}`\n\u{1F4B0} \u0645\u0628\u0644\u063A: *{amount:,} \u062A\u0648\u0645\u0627\u0646*\n\n\u{1F4CC} *\u0648\u0636\u0639\u06CC\u062A \u0641\u0639\u0644\u06CC:* \u0641\u06CC\u0634 \u062B\u0628\u062A \u0634\u062F \u0648 \u0648\u0627\u0631\u062F \u0635\u0641 \u0628\u0631\u0631\u0633\u06CC \u0634\u062F \u2705\n\n\u{1F50D} *\u0645\u0631\u062D\u0644\u0647 \u0628\u0639\u062F\u06CC:*\n\u0641\u06CC\u0634 \u062F\u0642\u06CC\u0642 \u0628\u0631\u0631\u0633\u06CC \u0645\u06CC\u200C\u0634\u0648\u062F \u0648 \u0628\u0639\u062F \u0627\u0632 \u062A\u0623\u06CC\u06CC\u062F\u060C \u0645\u0648\u062C\u0648\u062F\u06CC \u06A9\u06CC\u0641 \u067E\u0648\u0644 \u0634\u0645\u0627 \u0634\u0627\u0631\u0698 \u0645\u06CC\u200C\u0634\u0648\u062F.\n\n\u23F1 *\u0632\u0645\u0627\u0646 \u0628\u0631\u0631\u0633\u06CC:* \u0627\u0632 \u0686\u0646\u062F \u062F\u0642\u06CC\u0642\u0647 \u062A\u0627 \u0686\u0646\u062F \u0633\u0627\u0639\u062A (\u0628\u0633\u062A\u0647 \u0628\u0647 \u062A\u0639\u062F\u0627\u062F \u062F\u0631\u062E\u0648\u0627\u0633\u062A\u200C\u0647\u0627)\n\u0644\u0637\u0641\u0627\u064B \u0627\u06CC\u0646 \u0628\u0627\u0632\u0647 \u0631\u0627 \u0628\u0627 \u0635\u0628\u0648\u0631\u06CC \u0628\u0647 \u0645\u0627 \u0641\u0631\u0635\u062A \u062F\u0647\u06CC\u062F \u2764\uFE0F\n\n\u{1F33F} \u0634\u06A9\u0631\u06AF\u0632\u0627\u0631\u06CC\u0645 \u0627\u0632 \u0647\u0645\u0631\u0627\u0647\u06CC \u0648 \u062F\u0631\u06A9 \u0634\u0645\u0627",
    receipt_approved: "\u2705 \u0631\u0633\u06CC\u062F \u062A\u0623\u06CC\u06CC\u062F \u0634\u062F.\n+{amount:,} \u062A\u0648\u0645\u0627\u0646\n\u0645\u0648\u062C\u0648\u062F\u06CC: *{balance:,}*",
    receipt_rejected: "\u0631\u0633\u06CC\u062F \u0631\u062F \u0634\u062F.",
    history_empty: "\u0647\u0646\u0648\u0632 \u062D\u0631\u06A9\u062A\u06CC \u0646\u06CC\u0633\u062A.",
    history_title: " \u062A\u0627\u0631\u06CC\u062E\u0686\u0647 \u06A9\u06CC\u0641 \u067E\u0648\u0644",
    ref_view: " *\u0628\u0627\u0634\u06AF\u0627\u0647 \u0645\u0639\u0631\u0641\u06CC*\n\u0627\u0632 \u062E\u0631\u06CC\u062F \u0627\u0648\u0644 \u0647\u0631 \u062F\u0648\u0633\u062A\u060C \u0633\u0647\u0645 \u0645\u06CC\u200C\u06AF\u06CC\u0631\u06CC.\n\n{sep}\n\u0633\u0647\u0645 \u062A\u0648 \u0627\u0632 \u062E\u0631\u06CC\u062F \u0627\u0648\u0644: *{percent}%*\n\u06A9\u062F \u0627\u062E\u062A\u0635\u0627\u0635\u06CC: `{code}`\n\n\u0644\u06CC\u0646\u06A9 \u062F\u0639\u0648\u062A \u2014 \u0628\u0641\u0631\u0633\u062A \u062F\u0627\u062E\u0644 \u06AF\u0631\u0648\u0647 \u06CC\u0627 \u062F\u0627\u06CC\u0631\u06A9\u062A:\n{link}\n\n \u0639\u0645\u0644\u06A9\u0631\u062F\n\u062F\u0639\u0648\u062A\u200C\u0647\u0627\u06CC \u062B\u0628\u062A\u200C\u0634\u062F\u0647: *{count}*\n\u062F\u0631\u0622\u0645\u062F \u0648\u0627\u0631\u06CC\u0632\u0634\u062F\u0647 \u0628\u0647 \u06A9\u06CC\u0641 \u067E\u0648\u0644: *{earned:,} \u062A\u0648\u0645\u0627\u0646*\n\n\u067E\u0627\u062F\u0627\u0634 \u062E\u0648\u062F\u06A9\u0627\u0631 \u0628\u0639\u062F \u0627\u0632 \u0627\u0648\u0644\u06CC\u0646 \u062E\u0631\u06CC\u062F \u067E\u0648\u0644\u06CC \u062F\u0648\u0633\u062A\u062A \u0645\u06CC\u200C\u0622\u06CC\u062F.",
    account_view: " *\u067E\u0631\u0648\u0646\u062F\u0647 \u062D\u0633\u0627\u0628*\n\n\u0634\u0646\u0627\u0633\u0647 \u062A\u0644\u06AF\u0631\u0627\u0645: `{tgId}`\n\u0639\u0636\u0648\u06CC\u062A \u0627\u0632: *{joined}*\n\u0632\u0628\u0627\u0646 \u0631\u0627\u0628\u0637: *{lang}*\n\n \u06A9\u062F \u0645\u0639\u0631\u0641\u06CC \u062A\u0648\n`{code}`\n\u062F\u0639\u0648\u062A\u200C\u0647\u0627\u06CC \u062B\u0628\u062A\u200C\u0634\u062F\u0647: *{refCount}*\n\n\u0627\u06CC\u0646 \u06A9\u062F \u0631\u0627 \u0628\u0631\u0627\u06CC \u062F\u0648\u0633\u062A\u0627\u0646\u062A \u0628\u0641\u0631\u0633\u062A\u061B \u0627\u0632 \u062E\u0631\u06CC\u062F \u0627\u0648\u0644\u0634\u0627\u0646 \u0633\u0647\u0645 \u0645\u06CC\u200C\u06AF\u06CC\u0631\u06CC. \u062C\u0632\u0626\u06CC\u0627\u062A \u062F\u0631 \u0645\u0646\u0648\u06CC \u0645\u0639\u0631\u0641\u06CC \u0627\u0633\u062A.",
    trial_disabled: "\u0622\u0632\u0645\u0627\u06CC\u0634 \u0631\u0627\u06CC\u06AF\u0627\u0646 \u0641\u0639\u0627\u0644 \u0646\u06CC\u0633\u062A.",
    trial_already_used: "\u0633\u0647\u0645\u06CC\u0647 \u0622\u0632\u0645\u0627\u06CC\u0634 \u0631\u0627\u06CC\u06AF\u0627\u0646\u062A \u0645\u0635\u0631\u0641 \u0634\u062F\u0647.",
    trial_success: " *\u0622\u0632\u0645\u0627\u06CC\u0634 \u0631\u0627\u06CC\u06AF\u0627\u0646 \u0631\u0648\u0634\u0646 \u0634\u062F.*\n\n\u062D\u062C\u0645: *{gb} GB*\n\u0645\u062F\u062A: *{days} \u0631\u0648\u0632*\n\n \u0644\u06CC\u0646\u06A9 \u0631\u0627 \u0644\u0645\u0633 \u06A9\u0646 \u0648 \u062F\u0631 \u0627\u067E \u0648\u0627\u0631\u062F \u06A9\u0646:\n`{link}`\n\n\u0627\u06CC\u0646 \u0633\u0647\u0645\u06CC\u0647 \u06CC\u06A9\u200C\u0628\u0627\u0631 \u0627\u0633\u062A. \u0628\u0631\u0627\u06CC \u0627\u062F\u0627\u0645\u0647\u060C \u0627\u0632 \u0641\u0631\u0648\u0634\u06AF\u0627\u0647 \u067E\u0644\u0646 \u0628\u062E\u0631.",
    copied: "\u0644\u06CC\u0646\u06A9 \u0647\u0645\u06CC\u0646 \u0628\u0627\u0644\u0627\u0633\u062A \u2014 \u0644\u0645\u0633 \u06A9\u0646 \u0648 \u06A9\u067E\u06CC \u06A9\u0646.",
    invalid_amount: "\u0627\u06CC\u0646 \u0645\u0628\u0644\u063A \u0645\u0639\u062A\u0628\u0631 \u0646\u06CC\u0633\u062A.\n\u0641\u0642\u0637 \u0639\u062F\u062F \u0628\u0641\u0631\u0633\u062A\u060C \u0645\u062B\u0644\u0627\u064B `100000`.\n\u0627\u0639\u062F\u0627\u062F \u0641\u0627\u0631\u0633\u06CC \u0647\u0645 \u0642\u0628\u0648\u0644 \u0627\u0633\u062A.",
