function pnPanelProCSS() {
  return `
<style id="pn-panel-pro">
@font-face{font-family:'Vazirmatn';src:url('https://cdn.jsdelivr.net/gh/rastikerdar/vazirmatn@v33.003/fonts/webfonts/Vazirmatn-Regular.woff2') format('woff2');font-weight:400;font-display:swap}
@font-face{font-family:'Vazirmatn';src:url('https://cdn.jsdelivr.net/gh/rastikerdar/vazirmatn@v33.003/fonts/webfonts/Vazirmatn-Bold.woff2') format('woff2');font-weight:700;font-display:swap}
body{font-family:var(--font-ui)}
.nav-item{border-radius:12px!important;position:relative;transition:background .18s var(--pn-ease),color .18s,transform .12s}
.nav-item:hover{background:rgba(37,99,235,.08)}
.nav-item:active{transform:scale(.98)}
.nav-item.active{background:linear-gradient(90deg,rgba(37,99,235,.2),rgba(37,99,235,.05));box-shadow:inset 3px 0 0 var(--pn-blue)}
aside{border-inline-end:1px solid var(--pn-line)}
aside nav{scrollbar-width:thin}
#dash-box [id^="view-"]:not(.hidden){animation:pnViewIn .28s var(--pn-ease)}
@keyframes pnViewIn{from{opacity:0;transform:translateY(8px)}to{opacity:1;transform:none}}
#view-title{background:linear-gradient(90deg,#93c5fd,#60a5fa);-webkit-background-clip:text;background-clip:text;color:transparent}
.pn-ra-stat{border:1px solid var(--pn-line);border-radius:14px;transition:transform .18s var(--pn-ease),border-color .18s}
.pn-ra-stat:hover{transform:translateY(-2px);border-color:rgba(96,165,250,.4)}
.mobile-bottom-nav{backdrop-filter:blur(18px) saturate(160%);-webkit-backdrop-filter:blur(18px) saturate(160%);background:rgba(11,18,32,.86);border-top:1px solid var(--pn-line);padding-bottom:env(safe-area-inset-bottom,0px)}
.btn-top-bar{border-radius:12px!important}
.rounded-2xl{transition:box-shadow .18s ease}
input,select,textarea{font-family:var(--font-ui)}
</style>`;
}
